import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec3, color, mix, smoothstep, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, fontAtlas, textureLoader } = ctx;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find(item => item.role === 'headline') || items[0];

  const root = new Group();

  const atlasW = 512;
  const atlasH = 320;
  const cardWidth = 1.6;
  const cardHeight = cardWidth * (atlasH / atlasW);

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.FrontSide,
    depthWrite: false
  });

  const vUV = uv();
  const gradient = mix(color(colors.ink), color(colors.surface), smoothstep(0.0, 1.0, vUV.y));

  const noise = fract(sin(dot(vUV, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = noise.sub(0.5).mul(0.05);
  const staticSurface = gradient.add(vec3(grain));

  material.colorNode = staticSurface;

  const card = new Mesh(geometry, material);
  card.castShadow = false;
  card.receiveShadow = false;
  root.add(card);

  if (headline) {
    const label = fontAtlas.createText(headline.text, {
      fontSize: headline.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0
    });
    label.position.set(0, cardHeight * 0.55, 0.04);
    root.add(label);
  }

  let loadedTexture = null;
  const timelines = [];

  if (config.imageUrl) {
    textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;

      const texNode = texture(tex).sample(vUV);
      material.colorNode = mix(texNode, gradient.add(vec3(grain)), 0.12);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach(t => {
      try { t.kill(); } catch {}
    });
    if (loadedTexture) loadedTexture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return root;
}
